import os, sys, subprocess
import fsutil, gdiff, envcmd, logutil
import wcutil

HELP='''High-performance CLI proxy designed to filter and summarize system outputs before they reach your LLM context.

Usage: executable [OPTIONS] <COMMAND>

Commands: ls tree read smart git gh glab aws psql pnpm err test json deps env find diff log dotnet docker kubectl summary grep init wget wc gain config jest vitest prisma tsc next lint prettier format playwright cargo npm npx curl discover session telemetry learn run proxy pipe trust untrust verify ruff pytest mypy rake rubocop rspec pip go gt golangci-lint gradlew hook-audit rewrite hook

Options: -v, --verbose   --ultra-compact   --skip-env   -h, --help   -V, --version'''

def main(argv=None):
    args=list(sys.argv[1:] if argv is None else argv)
    if not args or args[0] in ('--help','-h','help'):
        print(HELP); return 0
    if args[0] in ('--version','-V'):
        print('rtk 0.42.0'); return 0
    # Global options may appear before the command.
    while args and args[0] in ('-v','-vv','-vvv','--ultra-compact','--skip-env'):
        args.pop(0)
    if not args: print(HELP); return 0
    cmd=args.pop(0)
    if cmd=='rewrite':
        from rewrite_util import rewrite
        if not args: return 0
        value,changed=rewrite(' '.join(args))
        if changed: print(value)
        return 0
    handled,rc=fsutil.handle(cmd,args)
    if handled:return rc
    if cmd in ('grep','diff'): return gdiff.do_grep(args) if cmd=='grep' else gdiff.do_diff(args)
    if cmd=='env':
        print(envcmd.env_output(args),end=''); return 0
    if cmd=='log':
        path=next((x for x in args if not x.startswith('-')),None)
        return logutil.run_log(path)
    if cmd=='run': return envcmd.run_command(args,True)
    if cmd=='proxy': return envcmd.run_command(args,False)
    if cmd=='wc':
        return wcutil.run_wc(args)
    # Commands not specialized yet should still behave as a command proxy.
    if cmd in ('git','gh','glab','aws','psql','pnpm','docker','kubectl','cargo','npm','npx','go','pip','wget','curl','tree'):
        return subprocess.call([cmd]+args)
    print(f"error: unrecognized subcommand '{cmd}'\n\n{HELP}",file=sys.stderr)
    return 2

if __name__=='__main__': sys.exit(main())
"}

